package com.smarthub.plus;
import android.os.*;import android.text.InputType;import android.widget.*;import org.json.JSONObject;import java.util.concurrent.*;
/** Real factory session setup; no launcher credentials are copied and passwords are never persisted. */
public final class FactorySettingsActivity extends HubActivity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private final Handler ui=new Handler(Looper.getMainLooper());private TextView status;private Button connect;private EditText serial,cid,pid,mid,user,password;private boolean closed;
 @Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout body=page(tx("ربط المصنع · CHMAX وEPG","Receiver link · CHMAX and EPG"));note(body,tx("يتصل هذا التلفزيون بخدمة المصنع باستخدام هويته الفعلية ويحفظ جلسة الوصول مشفّرة. لا يغيّر القنوات أو ملفات اللانشر. الصور والدليل يتبعان الترخيص والتغطية التي تمنحها الخدمة للجهاز.","This TV uses its actual receiver identity and stores the factory session encrypted. Channels and launcher files are preserved. Artwork and EPG availability follow the service's receiver licence and coverage."));CheckBox enabled=check(body,tx("جلب CHMAX وEPG تلقائياً عند تغيير القناة","Fetch CHMAX / EPG automatically on channel changes"),prefs().getBoolean("factory_enabled",true));enabled.setOnCheckedChangeListener((v,on)->prefs().edit().putBoolean("factory_enabled",on).apply());status=text(prefs().getString("factory_status","FACTORY_NOT_CONNECTED"),16,false);body.addView(status);note(body,tx("تُقرأ الهوية تلقائياً إن سمح Android بذلك. عند تعذّر قراءتها، أدخل بيانات رسيفرك من شاشة معلومات الجهاز. اترك الحقول فارغة للاحتفاظ بالهوية المحفوظة. لا ترسل الرقم أو كلمات المرور في المحادثة.","Identity is read automatically when Android allows it. Otherwise use your receiver's device-information screen. Blank fields preserve the saved identity. Do not post serial numbers or passwords in chat."));serial=field(body,"Receiver SN","");serial.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);cid=field(body,"CID","");pid=field(body,"PID","");mid=field(body,"MID","");for(EditText field:new EditText[]{cid,pid,mid})field.setInputType(InputType.TYPE_CLASS_NUMBER);user=field(body,tx("حساب المصنع اختياري","Factory account, optional"),"");password=field(body,tx("كلمة مرور الحساب · لا تُحفظ","Account password · never saved"),"");password.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);connect=action(body,tx("اختبار الاتصال وحفظ الجلسة","Test connection and save session"),this::connect);action(body,tx("إعادة اكتشاف خادم المصنع","Rediscover factory server"),()->{worker.execute(()->{try{JSONObject stored=FactoryVault.read(this);stored.remove("host");stored.remove("accessToken");stored.remove("refreshToken");stored.remove("expiresAt");FactoryVault.save(this,stored);prefs().edit().putString("factory_status","FACTORY_SERVER_RESET").apply();}catch(Exception e){prefs().edit().putString("factory_status",FactoryClient.safe(e)).apply();}});});note(body,tx("DVB/TXT: تُترجم المسارات النصية التي ينشرها المشغل. الترجمة المصوّرة الظاهرة تُقرأ عبر OCR المسموح من Android عند غياب مسار خام متاح.","DVB/TXT: text exposed by playback can be translated directly. Visible bitmap subtitles use Android-permitted OCR when no raw track is exposed."));action(body,tx("إعداد ترجمة DVB / TXT وحجم الخط","DVB / TXT translation and font size"),()->startActivity(new android.content.Intent(this,LiveTranslationActivity.class)));worker.execute(()->{try{boolean available=FactoryIdentity.valid(FactoryIdentity.read(this));prefs().edit().putBoolean("factory_identity_available",available).apply();}catch(Exception ignored){}});ui.post(tick);}
 private final Runnable tick=new Runnable(){public void run(){if(closed)return;status.setText(FactoryStatus.label(FactorySettingsActivity.this,prefs().getString("factory_status","FACTORY_NOT_CONNECTED"))+"\n"+tx("هوية متاحة: ","Identity available: ")+prefs().getBoolean("factory_identity_available",false)+"\n"+ReceiverDvbBridge.label(FactorySettingsActivity.this));ui.postDelayed(this,1000);}};
 private void connect(){String sn=serial.getText().toString().trim(),c=cid.getText().toString().trim(),p=pid.getText().toString().trim(),m=mid.getText().toString().trim(),u=user.getText().toString().trim(),pw=password.getText().toString();connect.setEnabled(false);prefs().edit().putString("factory_status","FACTORY_CONNECTING").apply();worker.execute(()->{try{JSONObject identity=FactoryIdentity.read(this);if(!sn.isEmpty())identity.put("sn",sn);if(!c.isEmpty())identity.put("cid",Integer.parseInt(c));if(!p.isEmpty())identity.put("pid",Integer.parseInt(p));if(!m.isEmpty())identity.put("mid",Integer.parseInt(m));if(!FactoryIdentity.valid(identity))throw new Exception("FACTORY_IDENTITY_REQUIRED");JSONObject saved=FactoryVault.read(this);saved.put("identity",identity);saved.remove("accessToken");saved.remove("refreshToken");saved.remove("expiresAt");FactoryVault.save(this,saved);new FactoryClient(this).authenticate(u,pw,true);prefs().edit().putString("factory_status","FACTORY_SESSION_VERIFIED").putBoolean("factory_identity_available",true).putLong("providers_changed_at",System.currentTimeMillis()).apply();}catch(Exception e){prefs().edit().putString("factory_status",FactoryClient.safe(e)).apply();}ui.post(()->{if(!closed){password.setText("");serial.setText("");connect.setEnabled(true);}});});}
 @Override protected void onDestroy(){closed=true;ui.removeCallbacksAndMessages(null);worker.shutdownNow();super.onDestroy();}
}
